// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Load font at module level to prevent flickering and ensure readiness
const { fontFamily: interFamily } = loadInter();

// ---------------------------------------------------------------------------
// SCHEMA DEFINITION
// ---------------------------------------------------------------------------


export type AdSpendProfitProps = Record<string, any>;

// ---------------------------------------------------------------------------
// HELPER COMPONENTS
// ---------------------------------------------------------------------------

const ChartBox: React.FC<{
  title: string;
  valueStr: string;
  color: string;
  pathStr: string;
  progress: number;
  gridColor: string;
  textColor: string;
  springValue: number;
  isVertical: boolean;
}> = ({
  title,
  valueStr,
  color,
  pathStr,
  progress,
  gridColor,
  textColor,
  springValue,
  isVertical,
}) => {
  // Generate safe unique IDs for SVG definitions based on the title
  const safeId = title.replace(/[^a-z0-9]/gi, "-").toLowerCase();
  const clipId = `clip-${safeId}`;
  const gradId = `grad-${safeId}`;

  return (
    <div
      style={{
        flex: 1,
        display: "flex",
        flexDirection: "column",
        backgroundColor: "rgba(255, 255, 255, 0.02)",
        borderRadius: "24px",
        padding: isVertical ? "32px" : "48px",
        border: `1px solid ${gridColor}`,
        opacity: springValue,
        transform: `translateY(${interpolate(springValue, [0, 1], [40, 0])}px)`,
        height: "100%",
        boxShadow: "0 20px 40px rgba(0,0,0,0.2)",
      }}
    >
      <div
        style={{
          color: gridColor,
          fontSize: isVertical ? "18px" : "24px",
          fontWeight: 600,
          textTransform: "uppercase",
          letterSpacing: "3px",
        }}
      >
        {title}
      </div>
      <div
        style={{
          color: color,
          fontSize: isVertical ? "64px" : "96px",
          fontWeight: 800,
          margin: isVertical ? "8px 0 24px 0" : "16px 0 40px 0",
          fontVariantNumeric: "tabular-nums",
          letterSpacing: "-0.03em",
          lineHeight: 1,
        }}
      >
        {valueStr}
      </div>

      <div style={{ flex: 1, position: "relative" }}>
        <svg
          viewBox="0 0 400 300"
          preserveAspectRatio="none"
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            overflow: "visible",
          }}
        >
          <defs>
            <clipPath id={clipId}>
              {/* Expand clip rect slightly to avoid cutting off strokes */}
              <rect x="-10" y="-10" width={progress * 420} height="320" />
            </clipPath>
            <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={color} stopOpacity={0.25} />
              <stop offset="100%" stopColor={color} stopOpacity={0} />
            </linearGradient>
          </defs>

          {/* Background Grid Lines */}
          {[50, 150, 250].map((y) => (
            <line
              key={y}
              x1="0"
              y1={y}
              x2="400"
              y2={y}
              stroke={gridColor}
              strokeWidth={2}
              strokeDasharray="8 8"
              opacity={0.4}
              vectorEffect="non-scaling-stroke"
            />
          ))}

          {/* Axes */}
          <line x1="0" y1="300" x2="400" y2="300" stroke={gridColor} strokeWidth={4} vectorEffect="non-scaling-stroke" opacity={0.6} />
          <line x1="0" y1="0" x2="0" y2="300" stroke={gridColor} strokeWidth={4} vectorEffect="non-scaling-stroke" opacity={0.6} />

          <g clipPath={`url(#${clipId})`}>
            {/* Area Fill */}
            <path
              d={`${pathStr} L 400 300 L 0 300 Z`}
              fill={`url(#${gradId})`}
            />

            {/* Faux Glow Layer (Soft thick stroke) */}
            <path
              d={pathStr}
              fill="none"
              stroke={color}
              strokeWidth={16}
              strokeLinecap="round"
              strokeLinejoin="round"
              opacity={0.15}
              vectorEffect="non-scaling-stroke"
            />

            {/* Main Trend Line */}
            <path
              d={pathStr}
              fill="none"
              stroke={color}
              strokeWidth={6}
              strokeLinecap="round"
              strokeLinejoin="round"
              vectorEffect="non-scaling-stroke"
            />
          </g>
        </svg>
      </div>
    </div>
  );
};

// ---------------------------------------------------------------------------
// MAIN COMPONENT
// ---------------------------------------------------------------------------

const AdSpendProfitAnimation: React.FC<AdSpendProfitProps> = ({
  backgroundColor = "#0b0f19",
  transparentBackground = false,
  durationInSeconds = 8,
  titleText = "Price vs Demand",
  adSpendLabel = "Product Price",
  adSpendStartValue = 500,
  adSpendEndValue = 100,
  adSpendColor = "#ef4444", // Red for dropping prices
  profitLabel = "Customer Demand",
  profitStartValue = 20.0,
  profitEndValue = 95.0,
  profitColor = "#10b981", // Emerald green for rising demand
  textColor = "#f8fafc",
  gridColor = "#334155",
}) => {
  const frame = useCurrentFrame();
  const { width, height, fps, durationInFrames } = useVideoConfig();
  const isVertical = height > width;

  // Handle transparent background request safely
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Formatting utilities
  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
      maximumFractionDigits: 0,
    }).format(val);
  };

  const formatPercent = (val: number) => {
    return `${val.toFixed(1)}%`;
  };

  // -------------------------------------------------------------------------
  // ANIMATION LOGIC
  // -------------------------------------------------------------------------

  // Staggered Entry Animations
  const titleSpring = spring({ fps, frame: frame - 5, config: { damping: 14 } });
  const leftSpring = spring({ fps, frame: frame - 15, config: { damping: 14 } });
  const rightSpring = spring({ fps, frame: frame - 25, config: { damping: 14 } });

  // Chart Progress Animation
  // Ensure the interpolation range is strictly monotonic (ascending)
  const chartStartFrame = 40;
  const chartEndFrame = Math.max(chartStartFrame + 1, durationInFrames - 30);
  
  const chartProgress = interpolate(
    frame,
    [chartStartFrame, chartEndFrame],
    [0, 1],
    {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
      easing: Easing.bezier(0.25, 1, 0.5, 1),
    }
  );

  // Interpolating the display values
  const currentAdSpend = interpolate(
    chartProgress,
    [0, 1],
    [adSpendStartValue, adSpendEndValue]
  );
  
  const currentProfit = interpolate(
    chartProgress,
    [0, 1],
    [profitStartValue, profitEndValue]
  );

  // Bezier Paths for visual representation 
  // ViewBox internal coordinates: 0,0 to 400,300
  const adSpendUpwardPath = "M 0 250 C 150 250 250 50 400 50";
  const profitDownwardPath = "M 0 50 C 150 50 250 250 400 250";

  // Dynamically map paths to trend direction (upward or downward)
  const pricePath = adSpendStartValue > adSpendEndValue ? profitDownwardPath : adSpendUpwardPath;
  const customersPath = profitStartValue > profitEndValue ? profitDownwardPath : adSpendUpwardPath;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        padding: isVertical ? "120px 48px" : "80px 100px",
        color: textColor,
        display: "flex",
        flexDirection: "column",
        transition: "none",
      }}
    >
      {/* Header Section */}
      <div
        style={{
          opacity: titleSpring,
          transform: `translateY(${interpolate(titleSpring, [0, 1], [-20, 0])}px)`,
          marginBottom: isVertical ? "40px" : "60px",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transition: "none",
        }}
      >
        <h1
          style={{
            fontSize: isVertical ? "48px" : "64px",
            fontWeight: 800,
            margin: 0,
            letterSpacing: "-0.02em",
            textAlign: "center",
          }}
        >
          {titleText}
        </h1>
        <div
          style={{
            width: "120px",
            height: "6px",
            backgroundColor: gridColor,
            marginTop: isVertical ? "16px" : "24px",
            borderRadius: "3px",
          }}
        />
      </div>

      {/* Charts Section */}
      <div
        style={{
          display: "flex",
          flexDirection: isVertical ? "column" : "row",
          flex: 1,
          gap: isVertical ? "40px" : "80px",
          transition: "none",
          paddingBottom: isVertical ? "40px" : "0px",
        }}
      >
        <ChartBox
          title={adSpendLabel}
          valueStr={formatCurrency(currentAdSpend)}
          color={adSpendColor}
          pathStr={pricePath}
          progress={chartProgress}
          gridColor={gridColor}
          textColor={textColor}
          springValue={leftSpring}
          isVertical={isVertical}
        />
        
        <ChartBox
          title={profitLabel}
          valueStr={formatPercent(currentProfit)}
          color={profitColor}
          pathStr={customersPath}
          progress={chartProgress}
          gridColor={gridColor}
          textColor={textColor}
          springValue={rightSpring}
          isVertical={isVertical}
        />
      </div>
    </AbsoluteFill>
  );
};

export default AdSpendProfitAnimation;